      '首頁創點子播放區正式播放：管理員在儀表板啟用並勾選「優秀作品（創星季參賽作品依按讚、附議、支持取前 8 名）／付費推播（加購推播且招募中的卡片，標示「推播」）／管理員自選」後，首頁最上方的創點子標誌換成輪播，每 5 秒換一個，滑鼠移上或手指按住暫停、可左右滑動，點一下打開該卡片；沒有可播放內容時仍顯示標誌。',
      '匯職缺找到職缺後，出現「把匯職缺加到主畫面」提示：瀏覽器支援直接安裝時（Chrome、Edge、Android）直接出現「安裝」鍵；iPhone／iPad 顯示「分享 → 加入主畫面」步驟與教學；已安裝或用 App 開啟時不顯示，關掉後 14 天內不再出現。',
      '修正匯職缺頁小燈泡、搜搜一閃一閃：檢查瀏覽器是否支援 3D 時，每次畫面更新都新建一個繪圖環境又不釋放，超過瀏覽器上限後最舊的被強制關掉；改成只檢查一次並立刻釋放。',
      '搜搜沒找到職缺時，抓抓頭後會「撲通」跪下、雙手撐地低頭，肩膀一抽一抽。',
      '搜搜的搜尋規定更新：同一個網站最多 20 筆、同一家公司最多 3 筆，盡量列 20 筆以上（先找符合所有條件的，不夠再逐步放寬條件湊滿），只要近 60 天內仍在刊登的職缺。',
