      '電腦版頁面變順：小燈泡、搜搜不再每一格都逼瀏覽器重算整頁排版（欄位多的頁面如個人資料特別明顯）；小燈泡表情沒變時不再重複上傳臉部貼圖、解析度上限從 2.5 倍降為 2 倍、閒著時改每秒 30 格；搜搜沒有風線時不再清整個畫面大小的畫布。',
