        title: '系統環境識別與四大運營模式切換 (四選一)',
        summary: '正式運營、無金流體驗、測試環境與競賽專屬模式之四選一互斥規範。',
        content: `### 系統運作環境狀態規範（平台運營模式四選一）

* **🟢 正式營運模式 (NORM)**：啟用真實懸賞金託管、專家身分驗證與交易發票開立，呈現純淨商業環境。
* **⚡ 無金流模式 (FREE)**：所有題目免收金流手續費，隱藏點數儲值與支付，提供初創團隊探索體驗。
* **🧪 測試環境 (TEST)**：啟用預設模擬數據、解封全部測試帳號一鍵切換與假金流模擬（僅管理員畫面）。
* **🏎️ 競賽模式 (RACE)**：舊站問題市場預設優先置頂「痛點專區」，痛點提出限定 L0 並附綠色「創星季」標籤與獨立網址，方案以競賽圖文卡片展示並含獨立網址；全站頁尾同步顯示英文簡稱 RACE。`,
