        content: `### 規則邏輯：條款聲明規則與商業邏輯總覽

#### 1. 條款聲明規則 (Terms & Disclaimers)
* **【服務協議與免責條款】**：平台作為資訊撮合與履約託管媒介，解答內容由專家獨立提供，平台提供雙向防偽與爭議調解，但不為專家解方實施之商業結果作無條件盈利保證。
* **【非公開保護與 NDA 協定】**：專家投標時預設簽署線上保密協定，未經提問方授權不得公開任何專案敏感資料或私案細節。
* **【身分與真實性聲明】**：提問者與解答者須同意遵守洗錢防制法 (AML) 與真實身分審查規範。

#### 2. 商業邏輯 (Business Logic & Economics)
* **【資金託管循環】**：發布懸賞 ➔ 平台安全託管 ➔ 專家提案競標 ➔ 提問者採納鎖定 ➔ 成果交付走查 ➔ 驗收確權撥付 ➔ 提領出金。
* **【平台階梯收費機制】**：基礎用戶抽成 10%~15%，Pro 訂閱會員優惠至 8%，Enterprise 旗艦會員 5%；提領免收平台手續費。
* **【點數等值機制】**：1 Idea Point = NT$ 1 元，具備不可逆之帳務稽核軌跡。`,
