        content: `### 手續費與分潤模型
* **基礎抽成**：平台標準服務費率為案件總額之 10% ~ 15%。
* **會員優惠**：Pro 會員享 8% 優惠費率；Enterprise 會員享 5%。
* **創作者分潤**：解答專家獲得案件總額之 85% ~ 95% 實收淨額。`,
