        content: `### 技術架構：技術性的類型、規格、紀錄與全景定義

#### 1. 技術性的類型 (Technical Types & Data Models)
* **【User 型別】**：包含 id, username, name, role ('admin' | 'questioner' | 'solver' | 'ambassador' | 'guest'), balance, withheldPoints, reputation, verifiedExpert, subscriptionTier 等核心欄位。
* **【Question 型別】**：包含 id, title, description, category (8 大領域), bounty, authorId, status ('open' | 'solved' | 'expired'), answersCount, solutions 等。
* **【Answer / Solution 型別】**：包含 id, questionId, solverId, summary, content, price, isAccepted, status 等。
* **【Transaction 型別】**：包含 id, userId, type ('recharge' | 'bounty_escrow' | 'payout' | 'refund'), amount, fee, status, timestamp。

#### 2. 技術規格 (Technical Specifications)
* **前端**：React 19 (SPA Architecture) + TypeScript 5.8 + Vite 8.3 + Tailwind CSS (Zero-Pill Discipline)。
* **資料庫雙引擎**：
  - **Firebase Firestore**：即時聊天通訊、即時線上狀態、系統推播通知。
  - **Cloud SQL (PostgreSQL)**：財務帳本日誌、交易併發鎖定、電子發票紀錄。
* **PWA 與快取**：Service Worker 靜態與資料快取、Web App Manifest (pwa-maskable-512x512.png)。

#### 3. 系統運行紀錄 (System Logs & State Tracking)
* **多模式切換紀錄**：正式營運 (NORM)、無金流體驗 (FREE)、測試模式 (TEST)、公開/隱藏測試帳號 (SHOW/HIDE)。
* **資安紀錄**：全站 AES-256 身分敏感數據加密、RBAC 五層級路由與操作權限阻擋、CSRF/XSS 淨化過濾。`,
